import React from "react";

export interface FAQItem {
  question: string;
  answer: string;
}

export interface SEOProps {
  title: string;
  description: string;
  canonical: string;
  keywords?: string;
  ogImage?: string;
  noIndex?: boolean;
  pageType?: "home" | "service" | "contact" | "portfolio" | "generic";
  serviceName?: string;
  serviceDescription?: string;
  breadcrumbs?: { name: string; url: string }[];
  faqs?: FAQItem[];
  datePublished?: string;
  dateModified?: string;
}

export const SITE_NAME = "JSK Fencing LLC";
export const SITE_URL = "https://www.jskfencing.com";
export const PHONE = "+17742360051";
export const EMAIL = "Jskfencingcape@gmail.com";
export const DEFAULT_OG_IMAGE = `${SITE_URL}/og-default.png`;

const LOCAL_BUSINESS_SCHEMA = {
  "@context": "https://schema.org",
  "@type": ["LocalBusiness", "HomeAndConstructionBusiness"],
  "@id": `${SITE_URL}/#business`,
  name: SITE_NAME,
  url: SITE_URL,
  logo: `${SITE_URL}/favicon.ico`,
  image: DEFAULT_OG_IMAGE,
  telephone: PHONE,
  email: EMAIL,
  description:
    "Expert fencing installation across Cape Cod & Massachusetts. Wood, vinyl, aluminum, chain-link, ornamental iron & custom gate solutions.",
  address: {
    "@type": "PostalAddress",
    streetAddress: "Centerville",
    addressLocality: "Centerville",
    addressRegion: "MA",
    postalCode: "02632",
    addressCountry: "US",
  },
  geo: {
    "@type": "GeoCoordinates",
    latitude: 41.6523,
    longitude: -70.3551,
  },
  areaServed: [
    { "@type": "City", name: "Centerville" },
    { "@type": "City", name: "Hyannis" },
    { "@type": "City", name: "Barnstable" },
    { "@type": "City", name: "Falmouth" },
    { "@type": "City", name: "Sandwich" },
    { "@type": "AdministrativeArea", name: "Cape Cod" },
    { "@type": "State", name: "Massachusetts" },
  ],
  priceRange: "$$",
  currenciesAccepted: "USD",
  paymentAccepted: "Cash, Check, Credit Card",
  openingHoursSpecification: [
    {
      "@type": "OpeningHoursSpecification",
      dayOfWeek: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"],
      opens: "08:00",
      closes: "18:00",
    },
    {
      "@type": "OpeningHoursSpecification",
      dayOfWeek: "Saturday",
      opens: "09:00",
      closes: "15:00",
    },
  ],
  hasOfferCatalog: {
    "@type": "OfferCatalog",
    name: "Fencing Services",
    itemListElement: [
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Wood Fencing Installation" } },
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Vinyl Fencing Installation" } },
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Aluminum Fencing Installation" } },
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Chain Link Fencing Installation" } },
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Ornamental Iron Fencing" } },
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Composite Fencing Installation" } },
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Mixed Material Fencing" } },
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Gate Installation & Automation" } },
      { "@type": "Offer", itemOffered: { "@type": "Service", name: "Fence Staining & Restoration" } },
    ],
  },
  sameAs: [],
};

export const SEO: React.FC<SEOProps> = ({
  title,
  description,
  canonical,
  keywords,
  ogImage = DEFAULT_OG_IMAGE,
  noIndex = false,
  pageType = "generic",
  serviceName,
  serviceDescription,
  breadcrumbs,
  faqs,
  datePublished = "2024-01-01",
  dateModified = new Date().toISOString().split("T")[0],
}) => {
  const fullTitle = `${title} | ${SITE_NAME}`;
  const canonicalUrl = `${SITE_URL}${canonical}`;

  // ── WebPage schema ──────────────────────────────────────────
  const webPageSchema: Record<string, any> = {
    "@context": "https://schema.org",
    "@type": pageType === "home" ? "WebSite" : pageType === "service" ? "WebPage" : "WebPage",
    "@id": `${canonicalUrl}#webpage`,
    url: canonicalUrl,
    name: fullTitle,
    description,
    inLanguage: "en-US",
    isPartOf: { "@id": `${SITE_URL}/#website` },
    datePublished,
    dateModified,
    breadcrumb: breadcrumbs
      ? { "@id": `${canonicalUrl}#breadcrumb` }
      : undefined,
  };

  if (pageType === "home") {
    webPageSchema["@type"] = "WebSite";
    webPageSchema.potentialAction = {
      "@type": "SearchAction",
      target: { "@type": "EntryPoint", urlTemplate: `${SITE_URL}/?s={search_term_string}` },
      "query-input": "required name=search_term_string",
    };
  }

  // ── Service schema ──────────────────────────────────────────
  const serviceSchema = serviceName
    ? {
        "@context": "https://schema.org",
        "@type": "Service",
        "@id": `${canonicalUrl}#service`,
        name: serviceName,
        description: serviceDescription || description,
        provider: { "@id": `${SITE_URL}/#business` },
        areaServed: { "@type": "AdministrativeArea", name: "Cape Cod, Massachusetts" },
        url: canonicalUrl,
        serviceType: serviceName,
        offers: {
          "@type": "Offer",
          availability: "https://schema.org/InStock",
          priceSpecification: {
            "@type": "PriceSpecification",
            priceCurrency: "USD",
          },
        },
      }
    : null;

  // ── BreadcrumbList schema ───────────────────────────────────
  const breadcrumbSchema = breadcrumbs
    ? {
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        "@id": `${canonicalUrl}#breadcrumb`,
        itemListElement: [
          {
            "@type": "ListItem",
            position: 1,
            name: "Home",
            item: SITE_URL,
          },
          ...breadcrumbs.map((b, i) => ({
            "@type": "ListItem",
            position: i + 2,
            name: b.name,
            item: `${SITE_URL}${b.url}`,
          })),
        ],
      }
    : null;

  // ── FAQPage schema ──────────────────────────────────────────
  const faqSchema =
    faqs && faqs.length > 0
      ? {
          "@context": "https://schema.org",
          "@type": "FAQPage",
          "@id": `${canonicalUrl}#faq`,
          mainEntity: faqs.map((f) => ({
            "@type": "Question",
            name: f.question,
            acceptedAnswer: {
              "@type": "Answer",
              text: f.answer,
            },
          })),
        }
      : null;

  return (
    <>
      <html lang="en" />
      <title>{fullTitle}</title>
      <meta charSet="utf-8" />
      <meta name="viewport" content="width=device-width, initial-scale=1" />
      <meta name="description" content={description} />
      {keywords && <meta name="keywords" content={keywords} />}
      <meta name="author" content={SITE_NAME} />
      <meta name="theme-color" content="#0b1f3a" />
      <link rel="canonical" href={canonicalUrl} />
      <link rel="icon" type="image/x-icon" href="/favicon.ico" />
      <meta name="robots" content={noIndex ? "noindex, nofollow" : "index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1"} />

      {/* Open Graph */}
      <meta property="og:type" content={pageType === "home" ? "website" : "article"} />
      <meta property="og:site_name" content={SITE_NAME} />
      <meta property="og:title" content={fullTitle} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={canonicalUrl} />
      <meta property="og:image" content={ogImage} />
      <meta property="og:image:width" content="1200" />
      <meta property="og:image:height" content="630" />
      <meta property="og:image:alt" content={title} />
      <meta property="og:locale" content="en_US" />

      {/* Twitter Card */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={fullTitle} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={ogImage} />
      <meta name="twitter:image:alt" content={title} />

      {/* Geo tags for local SEO */}
      <meta name="geo.region" content="US-MA" />
      <meta name="geo.placename" content="Centerville, Cape Cod, Massachusetts" />
      <meta name="geo.position" content="41.6523;-70.3551" />
      <meta name="ICBM" content="41.6523, -70.3551" />

      {/* Schemas */}
      <script type="application/ld+json">{JSON.stringify(LOCAL_BUSINESS_SCHEMA)}</script>
      <script type="application/ld+json">{JSON.stringify(webPageSchema)}</script>
      {serviceSchema && <script type="application/ld+json">{JSON.stringify(serviceSchema)}</script>}
      {breadcrumbSchema && <script type="application/ld+json">{JSON.stringify(breadcrumbSchema)}</script>}
      {faqSchema && <script type="application/ld+json">{JSON.stringify(faqSchema)}</script>}
    </>
  );
};
